/* eslint-disable max-len */

'use strict';

// MODULES //

var reinterpret = require( '@stdlib/strided/base/reinterpret-complex64' );
var format = require( '@stdlib/string/format' );
var addon = require( './../src/addon.node' );


// MAIN //

/**
* Generates a single-precision complex floating-point Vandermonde matrix.
*
* @param {integer} mode - mode indicating whether to generate increasing or decreasing powers
* @param {NonNegativeInteger} M - number of rows in `out`
* @param {NonNegativeInteger} N - number of columns in `out`
* @param {Complex64Array} x - input array
* @param {integer} strideX - stride length for `x`
* @param {NonNegativeInteger} offsetX - starting index for `x`
* @param {Complex64Array} out - output matrix
* @param {integer} strideOut1 - stride length for the first dimension of `out`
* @param {integer} strideOut2 - stride length for the second dimension of `out`
* @param {NonNegativeInteger} offsetOut - starting index for `out`
* @throws {RangeError} second argument must be a nonnegative integer
* @throws {RangeError} third argument must be a nonnegative integer
* @returns {Complex64Array} output matrix
*
* @example
* var Complex64Array = require( '@stdlib/array/complex64' );
*
* var x = new Complex64Array( [ 1.0, 0.0, 2.0, 0.0 ] );
* var out = new Complex64Array( 6 );
*
* cvander( -1, 2, 3, x, 1, 0, out, 3, 1, 0 );
* // out => <Complex64Array>[ 1.0, 0.0, 1.0, 0.0, 1.0, 0.0, 4.0, 0.0, 2.0, 0.0, 1.0, 0.0 ]
*/
function cvander( mode, M, N, x, strideX, offsetX, out, strideOut1, strideOut2, offsetOut ) {
	if ( M < 0 ) {
		throw new RangeError( format( 'invalid argument. Second argument must be a nonnegative integer. Value: `%d`.', M ) );
	}
	if ( N < 0 ) {
		throw new RangeError( format( 'invalid argument. Third argument must be a nonnegative integer. Value: `%d`.', N ) );
	}
	if ( M === 0 || N === 0 ) {
		return out;
	}
	addon.ndarray( mode, M, N, reinterpret( x, 0 ), strideX, offsetX, reinterpret( out, 0 ), strideOut1, strideOut2, offsetOut );
	return out;
}


// EXPORTS //

module.exports = cvander;
